  document.addEventListener('keydown',function(e){if(/INPUT|TEXTAREA|SELECT/.test(e.target.tagName))return;if(!L)return;if(e.key==='ArrowLeft'||e.key===' '||e.key==='PageDown'){e.preventDefault();next()}else if(e.key==='ArrowRight'||e.key==='PageUp'){e.preventDefault();OX.go(idx-1)}else if(e.key==='Escape')$$('.ov').forEach(function(x){x.remove()})});
