/* اكتشف الخطأ: المس الكلمة الخاطئة فتظهر التصحيح */
OX.spot=function(box,items,key){var w=h('<div class="col"></div>');items.forEach(function(it,k){var d=h('<div class="cd"><div class="qno">🔍 اكتشف الخطأ '+n(k+1)+'</div><div class="spot">'+it.p.map(function(t,i){return '<span data-i="'+i+'">'+t+'</span>'}).join(' ')+'</div><div class="fbx"></div></div>');
   var tries=0,ok=false;$$('.spot span',d).forEach(function(s){s.onclick=function(){if(ok)return;var i=+s.dataset.i;if(i===it.w){ok=true;s.classList.add('bad');var f=h('<span class="fix">'+it.fix+'</span>');s.after(f);sfx.ok();$('.fbx',d).innerHTML='<div class="fb ok">✔ وجدتم الخطأ! '+(it.ex||'')+'</div>';if(key)$('.fbx',d).appendChild(OX.award(key+'-'+k,tries?5:10))}else{tries++;s.classList.add('miss');setTimeout(function(){s.classList.remove('miss')},400);sfx.no()}}});w.appendChild(d)});box.appendChild(w);return w};
